use xiom.io;

use xiom.string;
fn get_config(key: Str) -> Option[Str] {
  if key == "host" { return Some("0.0.0.0"); }
  elif key == "port" { return Some("8080"); }
  elif key == "debug" { return Some("true"); }
  elif key == "name" { return Some("WebServer"); }
  else { return None; }
}

fn get_required(key: Str) -> Result[Str, Str] {
  match get_config(key) {
    Some(val) => { return Ok(val); }
    None => { return Err("Missing config: " + key); }
  }
}

fn start_server() -> Result[Str, Str] {
  let host = get_required("host")?;
  let port_str = get_required("port")?;
  let port = string.str_to_int(port_str);
  let p = match port {
    Ok(val) => {
      if val < 1 || val > 65535 { return Err("Invalid port range"); }
      val;
    }
    Err(_) => { return Err("Port must be a number"); }
  };
  let debug = get_config("debug").unwrap_or("false");
  let name = get_config("name").unwrap_or("Unnamed");
  return Ok(name + " running on " + host + ":" + p);
}

fn main() -> Int {
  match start_server() {
    Ok(_) => { return 200; }
    Err(_) => { return 500; }
  }
}
